import { useContext } from "react";
import { useNavigate } from "react-router-dom";
import { ComplaintContext } from "../context/ComplaintContext";
import StatsCard from "../components/StatsCard";

function Dashboard() {
  const { complaints } = useContext(ComplaintContext);

  const pending = complaints.filter(c => c.status === "pending").length;
  const progress = complaints.filter(c => c.status === "in-progress").length;
  const resolved = complaints.filter(c => c.status === "resolved").length;
  const navigate = useNavigate();

const departments = [
  { name: "Public Works", icon: "🏗" },
  { name: "Water & Sanitation", icon: "💧" },
  { name: "Health & Safety", icon: "🏥" }
];

  return (
    <div className="dashboard">
      <StatsCard title="Pending" count={pending} />
      <StatsCard title="In Progress" count={progress} />
      <StatsCard title="Resolved" count={resolved} />
    </div>
  );
}
export default Dashboard;
